CREATE OR REPLACE FUNCTION public.actor_can_analyze_booking(p_booking_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b public.property_bookings; p public.properties;
BEGIN
 IF auth.uid() IS NULL THEN RETURN false; END IF;
 SELECT * INTO b FROM public.property_bookings WHERE id=p_booking_id;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO p FROM public.properties WHERE id=b.property_id;
 IF NOT FOUND THEN RETURN false; END IF;
 IF public.actor_has_platform_admin() OR b.guest_id=auth.uid() OR p.owner_id=auth.uid() THEN RETURN true; END IF;
 RETURN public.actor_can_operate_property(p.id,p.management_company_id,'bookings','view');
END $function$

CREATE OR REPLACE FUNCTION public.actor_can_operate_property(p_property_id uuid, p_company_id uuid, p_module text, p_action text DEFAULT 'view'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE enforced boolean; actor uuid := auth.uid();
BEGIN
 IF p_company_id IS NULL OR p_module NOT IN ('properties','bookings','tasks','reports','finance') OR p_action NOT IN ('view','edit','export') THEN RETURN false; END IF;
 IF NOT public.actor_property_scope_ceiling(p_property_id,p_company_id) THEN RETURN false; END IF;
 SELECT operating_spaces_enforced INTO enforced FROM public.management_companies WHERE id=p_company_id;
 IF enforced IS FALSE THEN
   RETURN public.staff_can_access_property_e28_private(actor,p_property_id) AND public.mc_can_access_e28_private(actor,p_company_id,p_module,p_action);
 END IF;
 IF public.actor_is_operating_company_overseer(p_company_id) THEN RETURN public.mc_can_access_e28_private(actor,p_company_id,p_module,p_action); END IF;
 -- Do not inherit mc_can_access's generic uno_team bypass in enforced mode.
 RETURN EXISTS(SELECT 1 FROM public.management_company_members m JOIN public.team_member_permissions t
 ON t.company_id=m.company_id AND t.user_id=m.user_id
 WHERE m.company_id=p_company_id AND m.user_id=actor AND m.is_active IS TRUE AND t.module=p_module
 AND CASE p_action WHEN 'view' THEN t.can_view WHEN 'edit' THEN t.can_edit WHEN 'export' THEN t.can_export ELSE false END
 AND (m.role <> 'staff' OR EXISTS(SELECT 1 FROM public.property_manager_assignments a
 WHERE a.property_id=p_property_id AND a.manager_user_id=actor AND a.is_active IS TRUE)));
END $function$

CREATE OR REPLACE FUNCTION public.calculate_order_commission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_commission_rate NUMERIC;
  v_provider_rate NUMERIC;
  v_vertical_rule RECORD;
  v_vertical TEXT;
BEGIN
  IF NEW.platform_fee_amount IS NOT NULL AND NEW.platform_fee_amount > 0 THEN RETURN NEW; END IF;
  IF NEW.total_amount IS NULL OR NEW.total_amount <= 0 THEN RETURN NEW; END IF;

  v_vertical := public.get_order_vertical(NEW.order_type, NEW.metadata);
  NEW.vertical := v_vertical;

  SELECT commission_rate INTO v_provider_rate FROM providers WHERE id = NEW.provider_org_id;

  IF v_provider_rate IS NOT NULL AND v_provider_rate > 0 THEN
    v_commission_rate := v_provider_rate / 100;
  ELSE
    SELECT * INTO v_vertical_rule FROM vertical_commission_rules
    WHERE vertical = v_vertical AND is_active = true;
    IF FOUND THEN
      IF v_vertical_rule.tiered_rates IS NOT NULL THEN
        SELECT rate INTO v_commission_rate
        FROM jsonb_to_recordset(v_vertical_rule.tiered_rates->'tiers')
          AS t(min_gmv NUMERIC, max_gmv NUMERIC, rate NUMERIC)
        WHERE NEW.total_amount >= min_gmv AND (max_gmv IS NULL OR NEW.total_amount < max_gmv)
        LIMIT 1;
      END IF;
      IF v_commission_rate IS NULL THEN v_commission_rate := v_vertical_rule.base_commission; END IF;
      -- Rules are stored as percent (10.00 = 10%); values <= 1 are legacy fractions.
      IF v_commission_rate > 1 THEN v_commission_rate := v_commission_rate / 100; END IF;
      IF v_vertical_rule.min_commission_amount IS NOT NULL THEN
        v_commission_rate := GREATEST(v_commission_rate, v_vertical_rule.min_commission_amount / NULLIF(NEW.total_amount, 0));
      END IF;
      IF v_vertical_rule.max_commission_amount IS NOT NULL THEN
        v_commission_rate := LEAST(v_commission_rate, v_vertical_rule.max_commission_amount / NULLIF(NEW.total_amount, 0));
      END IF;
    ELSE
      v_commission_rate := 0.10;
    END IF;
  END IF;

  v_commission_rate := LEAST(GREATEST(v_commission_rate, 0), 1);
  NEW.commission_rate_applied := v_commission_rate;
  NEW.platform_fee_amount := ROUND(NEW.total_amount * v_commission_rate, 2);
  NEW.vendor_payout_amount := NEW.total_amount - NEW.platform_fee_amount;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_order_totals(p_base_amount numeric, p_vertical text DEFAULT 'service'::text, p_provider_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_commission_rate NUMERIC := 0.10; -- default 10%
  v_provider_rate NUMERIC;
  v_vertical_rule RECORD;
  v_platform_fee NUMERIC;
  v_vendor_amount NUMERIC;
  v_service_fee NUMERIC := 0; -- optional customer service fee
BEGIN
  -- 1. Check provider-specific rate
  IF p_provider_id IS NOT NULL THEN
    SELECT commission_rate INTO v_provider_rate
    FROM providers
    WHERE id = p_provider_id;

    IF v_provider_rate IS NOT NULL AND v_provider_rate > 0 THEN
      v_commission_rate := v_provider_rate / 100;
    END IF;
  END IF;

  -- 2. If no provider rate, check vertical rules
  IF v_provider_rate IS NULL OR v_provider_rate = 0 THEN
    SELECT * INTO v_vertical_rule
    FROM vertical_commission_rules
    WHERE vertical = p_vertical AND is_active = true;

    IF FOUND THEN
      -- Check for tiered rates
      IF v_vertical_rule.tiered_rates IS NOT NULL THEN
        SELECT rate INTO v_commission_rate
        FROM jsonb_to_recordset(v_vertical_rule.tiered_rates->'tiers') 
          AS t(min_gmv NUMERIC, max_gmv NUMERIC, rate NUMERIC)
        WHERE p_base_amount >= min_gmv 
          AND (max_gmv IS NULL OR p_base_amount < max_gmv)
        LIMIT 1;
      END IF;

      IF v_commission_rate IS NULL OR v_commission_rate = 0 THEN
        v_commission_rate := COALESCE(v_vertical_rule.base_commission, 0.10);
      END IF;
    END IF;
  END IF;

  -- Calculate fees
  v_platform_fee := ROUND(p_base_amount * v_commission_rate, 2);
  v_vendor_amount := p_base_amount - v_platform_fee;

  -- Return all calculated values
  RETURN json_build_object(
    'base_amount', p_base_amount,
    'commission_rate', v_commission_rate,
    'platform_fee', v_platform_fee,
    'vendor_amount', v_vendor_amount,
    'service_fee', v_service_fee,
    'total_customer_pays', p_base_amount + v_service_fee
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_order_totals(p_base_amount numeric, p_vertical text DEFAULT 'service'::text, p_provider_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_commission_rate NUMERIC := 0.10; -- Default 10%
  v_platform_fee NUMERIC;
  v_vendor_amount NUMERIC;
  v_service_fee NUMERIC := 0;
  v_total_customer_pays NUMERIC;
  v_product_rate NUMERIC;
  v_provider_rate NUMERIC;
  v_vertical_rule RECORD;
BEGIN
  -- 1. Check product-specific rate (NEW - highest priority)
  IF p_product_id IS NOT NULL THEN
    v_product_rate := get_product_commission(p_product_id, p_vertical);
    IF v_product_rate IS NOT NULL THEN
      v_commission_rate := v_product_rate;
    END IF;
  END IF;

  -- 2. Check provider custom rate (if no product rate)
  IF v_product_rate IS NULL AND p_provider_id IS NOT NULL THEN
    SELECT commission_rate INTO v_provider_rate
    FROM providers
    WHERE id = p_provider_id;

    IF v_provider_rate IS NOT NULL THEN
      v_commission_rate := v_provider_rate / 100; -- Convert from percentage
    END IF;
  END IF;

  -- 3. Check vertical rules (if no provider rate)
  IF v_product_rate IS NULL AND v_provider_rate IS NULL THEN
    SELECT * INTO v_vertical_rule
    FROM vertical_commission_rules
    WHERE vertical = p_vertical AND is_active = true;

    IF v_vertical_rule.base_commission IS NOT NULL THEN
      v_commission_rate := v_vertical_rule.base_commission / 100;
    END IF;
  END IF;

  -- Calculate platform fee
  v_platform_fee := ROUND(p_base_amount * v_commission_rate, 2);

  -- Apply min/max caps from vertical rules if applicable
  IF v_vertical_rule IS NOT NULL THEN
    IF v_vertical_rule.min_commission_amount IS NOT NULL AND v_platform_fee < v_vertical_rule.min_commission_amount THEN
      v_platform_fee := v_vertical_rule.min_commission_amount;
    END IF;
    IF v_vertical_rule.max_commission_amount IS NOT NULL AND v_platform_fee > v_vertical_rule.max_commission_amount THEN
      v_platform_fee := v_vertical_rule.max_commission_amount;
    END IF;
  END IF;

  -- Calculate vendor amount
  v_vendor_amount := p_base_amount - v_platform_fee;

  -- Total customer pays (no additional service fee for now)
  v_total_customer_pays := p_base_amount;

  RETURN json_build_object(
    'base_amount', p_base_amount,
    'commission_rate', v_commission_rate,
    'platform_fee', v_platform_fee,
    'vendor_amount', v_vendor_amount,
    'service_fee', v_service_fee,
    'total_customer_pays', v_total_customer_pays
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_expired_google_place_cache()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM public.google_place_cache WHERE expires_at < now();
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_booking_with_wallet_payment(p_user_id uuid, p_booking_type text, p_scheduled_at timestamp with time zone, p_total_amount numeric, p_currency text, p_provider_id uuid DEFAULT NULL::uuid, p_service_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wallet_id UUID;
  v_balance NUMERIC;
  v_booking_id UUID;
BEGIN
  -- Get wallet and lock row
  SELECT id, balance INTO v_wallet_id, v_balance
  FROM wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    RAISE EXCEPTION 'Wallet not found';
  END IF;

  IF v_balance < p_total_amount THEN
    RAISE EXCEPTION 'Insufficient balance';
  END IF;

  -- Create booking first
  INSERT INTO bookings (
    user_id, booking_type, status, scheduled_at, 
    total_amount, currency, provider_id, service_id, notes
  ) VALUES (
    p_user_id, p_booking_type::booking_type, 'confirmed', p_scheduled_at,
    p_total_amount, p_currency, p_provider_id, p_service_id, p_notes
  )
  RETURNING id INTO v_booking_id;

  -- Deduct from wallet
  UPDATE wallets 
  SET balance = balance - p_total_amount, updated_at = now()
  WHERE id = v_wallet_id;

  -- Record transaction
  INSERT INTO wallet_transactions (wallet_id, user_id, amount, type, description, status, reference_id)
  VALUES (v_wallet_id, p_user_id, -p_total_amount, 'payment', 'Booking payment', 'completed', v_booking_id);

  -- Record payment
  INSERT INTO booking_payments (booking_id, amount, payment_method, status, paid_at, currency)
  VALUES (v_booking_id, p_total_amount, 'wallet', 'completed', now(), p_currency);

  RETURN v_booking_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_financial_from_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_owner_id UUID;
  v_property_id UUID;
  v_nights INTEGER;
  v_total_rent NUMERIC;
  v_cleaning_fee NUMERIC;
BEGIN
  IF NEW.status = 'confirmed' AND (OLD IS NULL OR OLD.status != 'confirmed') THEN
    SELECT owner_id, id INTO v_property_owner_id, v_property_id
    FROM owner_properties WHERE id = NEW.property_id;
    IF v_property_owner_id IS NULL THEN RETURN NEW; END IF;

    v_nights := GREATEST(1, NEW.check_out::date - NEW.check_in::date);
    v_total_rent := COALESCE(NEW.total_amount, 0);
    v_cleaning_fee := COALESCE(NEW.cleaning_fee, 0);

    IF v_total_rent > 0 THEN
      INSERT INTO property_financials (
        property_id, owner_id, transaction_type, category, amount, currency,
        description, description_ru, reference_type, reference_id, transaction_date, status, payment_method
      ) VALUES (
        v_property_id, v_property_owner_id, 'income', 'rent', v_total_rent,
        COALESCE(NEW.currency, 'THB'),
        'Rental income: ' || COALESCE(NEW.guest_name, 'Guest') || ' (' || v_nights || ' nights)',
        'Доход от аренды: ' || COALESCE(NEW.guest_name, 'Гость') || ' (' || v_nights || ' ночей)',
        'booking', NEW.id, NEW.check_in, 'paid',
        COALESCE(NEW.deposit_payment_method, 'platform')
      );
    END IF;

    IF v_cleaning_fee > 0 THEN
      INSERT INTO property_financials (
        property_id, owner_id, transaction_type, category, amount, currency,
        description, description_ru, reference_type, reference_id, transaction_date, status
      ) VALUES (
        v_property_id, v_property_owner_id, 'income', 'cleaning_fee', v_cleaning_fee,
        COALESCE(NEW.currency, 'THB'),
        'Cleaning fee: ' || COALESCE(NEW.guest_name, 'Guest'),
        'Плата за уборку: ' || COALESCE(NEW.guest_name, 'Гость'),
        'booking', NEW.id, NEW.check_in, 'paid'
      );
    END IF;

    INSERT INTO property_activity_log (property_id, actor_id, actor_role, action, details)
    VALUES (
      v_property_id, v_property_owner_id, 'system', 'booking_confirmed',
      jsonb_build_object('booking_id', NEW.id, 'guest_name', NEW.guest_name,
        'check_in', NEW.check_in, 'check_out', NEW.check_out,
        'total_amount', v_total_rent, 'cleaning_fee', v_cleaning_fee)
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_order_atomic(p_order_type text, p_customer_user_id uuid, p_provider_org_id uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_total_amount numeric DEFAULT 0, p_currency text DEFAULT 'THB'::text, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_items jsonb DEFAULT '[]'::jsonb, p_participants jsonb DEFAULT '[]'::jsonb, p_addresses jsonb DEFAULT '[]'::jsonb, p_payment_method text DEFAULT NULL::text, p_payment_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_item JSONB;
  v_participant JSONB;
  v_address JSONB;
BEGIN
  -- Create order
  INSERT INTO public.orders (
    order_type, customer_user_id, provider_org_id,
    status, start_at, end_at, total_amount, currency, notes, metadata
  ) VALUES (
    p_order_type, p_customer_user_id, p_provider_org_id,
    'pending', p_start_at, p_end_at, p_total_amount, p_currency, p_notes, p_metadata
  )
  RETURNING id, order_number INTO v_order_id, v_order_number;

  -- Insert items
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      INSERT INTO public.order_items (
        order_id, product_id, resource_id, provider_org_id,
        item_name, item_type, qty, unit_price, amount, 
        start_at, end_at, metadata
      ) VALUES (
        v_order_id,
        NULLIF(v_item->>'product_id', '')::uuid,
        NULLIF(v_item->>'resource_id', '')::uuid,
        COALESCE(NULLIF(v_item->>'provider_org_id', '')::uuid, p_provider_org_id),
        v_item->>'item_name',
        COALESCE(v_item->>'item_type', 'service'),
        COALESCE((v_item->>'qty')::int, 1),
        COALESCE((v_item->>'unit_price')::numeric, 0),
        COALESCE((v_item->>'amount')::numeric, 0),
        NULLIF(v_item->>'start_at', '')::timestamptz,
        NULLIF(v_item->>'end_at', '')::timestamptz,
        COALESCE(v_item->'metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  -- Insert participants
  IF p_participants IS NOT NULL AND jsonb_array_length(p_participants) > 0 THEN
    FOR v_participant IN SELECT * FROM jsonb_array_elements(p_participants)
    LOOP
      INSERT INTO public.order_participants (
        order_id, role, name, phone, email
      ) VALUES (
        v_order_id,
        COALESCE(v_participant->>'role', 'primary'),
        v_participant->>'name',
        v_participant->>'phone',
        v_participant->>'email'
      );
    END LOOP;
  END IF;

  -- Insert addresses
  IF p_addresses IS NOT NULL AND jsonb_array_length(p_addresses) > 0 THEN
    FOR v_address IN SELECT * FROM jsonb_array_elements(p_addresses)
    LOOP
      INSERT INTO public.order_addresses (
        order_id, address_type, address_text, lat, lng, notes
      ) VALUES (
        v_order_id,
        v_address->>'address_type',
        v_address->>'address_text',
        NULLIF(v_address->>'lat', '')::numeric,
        NULLIF(v_address->>'lng', '')::numeric,
        v_address->>'notes'
      );
    END LOOP;
  END IF;

  -- Create payment intent if provided (cast text to payment_method enum)
  IF p_payment_method IS NOT NULL AND p_payment_amount IS NOT NULL THEN
    INSERT INTO public.payment_intents (
      order_id, amount, currency, method, status
    ) VALUES (
      v_order_id, p_payment_amount, p_currency, p_payment_method::payment_method, 'pending'
    );
  END IF;

  -- Record initial status in history
  INSERT INTO public.order_status_history (
    order_id, from_status, to_status, actor_user_id, reason
  ) VALUES (
    v_order_id, NULL, 'pending', p_customer_user_id, 'Order created'
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_order_checked(p_order_type text, p_provider_org_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_total_amount numeric, p_currency text, p_notes text, p_metadata jsonb, p_items jsonb, p_participants jsonb, p_addresses jsonb, p_payment_method text, p_payment_amount numeric, p_customer_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_customer uuid; v_staff boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
  v_staff := public.is_finance_staff_e28_private(v_uid);
  v_customer := CASE WHEN v_staff AND p_customer_user_id IS NOT NULL THEN p_customer_user_id ELSE v_uid END;
  IF p_total_amount IS NULL OR p_total_amount <= 0 OR p_total_amount > 100000000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_amount'); END IF;
  IF p_payment_amount IS NOT NULL AND (p_payment_amount < 0 OR p_payment_amount > p_total_amount) THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_amount'); END IF;
  IF NOT v_staff AND p_payment_method = 'wallet' THEN
    RETURN jsonb_build_object('success', false, 'error', 'wallet_payment_not_allowed'); END IF;
  IF p_provider_org_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.orgs WHERE id = p_provider_org_id AND coalesce(is_active, true)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'org_not_found'); END IF;
  RETURN public.create_order_atomic(p_order_type, v_customer, p_provider_org_id, p_start_at, p_end_at,
    p_total_amount, p_currency, p_notes, p_metadata, p_items, p_participants, p_addresses,
    p_payment_method, p_payment_amount);
END $function$

CREATE OR REPLACE FUNCTION public.create_property_booking_from_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_id uuid;
  v_owner_id uuid;
  v_guest_name text;
  v_guest_phone text;
  v_guest_email text;
  v_check_in date;
  v_check_out date;
  v_source text;
  v_source_calendar_id uuid;
BEGIN
  -- Only for property vertical orders that become confirmed
  IF NEW.vertical != 'property' THEN
    RETURN NEW;
  END IF;

  IF NEW.status != 'confirmed' THEN
    RETURN NEW;
  END IF;

  -- Skip if already confirmed before (update case)
  IF OLD IS NOT NULL AND OLD.status = 'confirmed' THEN
    RETURN NEW;
  END IF;

  -- Get property_id from order_items metadata
  SELECT (oi.metadata->>'property_id')::uuid
  INTO v_property_id
  FROM order_items oi 
  WHERE oi.order_id = NEW.id AND oi.item_type = 'property'
  LIMIT 1;

  IF v_property_id IS NULL THEN
    RETURN NEW; -- no property linked, skip
  END IF;

  -- Get owner_id from owner_properties
  SELECT op.owner_id INTO v_owner_id
  FROM owner_properties op WHERE op.id = v_property_id;

  IF v_owner_id IS NULL THEN
    RETURN NEW; -- property not found in owner_properties, skip
  END IF;

  -- Get guest info from order_participants
  SELECT p.name, p.phone, p.email
  INTO v_guest_name, v_guest_phone, v_guest_email
  FROM order_participants p
  WHERE p.order_id = NEW.id AND p.role = 'guest'
  LIMIT 1;

  -- Fallback to metadata
  IF v_guest_name IS NULL THEN
    v_guest_name := NEW.metadata->>'guest_name';
  END IF;

  -- Dates from order
  v_check_in := (NEW.start_at AT TIME ZONE 'Asia/Bangkok')::date;
  v_check_out := (NEW.end_at AT TIME ZONE 'Asia/Bangkok')::date;

  IF v_check_in IS NULL OR v_check_out IS NULL THEN
    RETURN NEW;
  END IF;

  -- Source info
  v_source := COALESCE(NEW.metadata->>'source', 'manual');
  v_source_calendar_id := (NEW.metadata->>'source_calendar_id')::uuid;

  -- Insert booking, skip if already exists for this order
  INSERT INTO property_bookings (
    property_id, owner_id, guest_name, guest_phone, guest_email,
    check_in, check_out, total_amount, currency, source,
    source_calendar_id, status, order_id, guest_id
  ) VALUES (
    v_property_id, v_owner_id, v_guest_name, v_guest_phone, v_guest_email,
    v_check_in, v_check_out, NEW.total_amount, COALESCE(NEW.currency, 'THB'), v_source,
    v_source_calendar_id, 'confirmed', NEW.id, NEW.customer_user_id
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.devmod_set_attribution_expiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
